import unittest

from shelf.loader import load_csv


class LoadCsv(unittest.TestCase):
    def test_empty_qty_is_not_counted_yet(self):
        items = load_csv("sku,name,qty,reorder_at\nD4,rivets,,5\n")
        self.assertIsNone(items[0].qty)

    def test_zero_qty_is_out_of_stock(self):
        items = load_csv("sku,name,qty,reorder_at\nC3,washers,0,5\n")
        self.assertEqual(items[0].qty, 0)

    def test_empty_reorder_at_uses_default(self):
        items = load_csv("sku,name,qty,reorder_at\nA1,bolts,3,\n")
        self.assertEqual(items[0].reorder_at, 5)


if __name__ == "__main__":
    unittest.main()
